10-dom-01-dom-selectors.solution:
function closestPolyfill(el, selector) {
  let current = el;
  while (current) {
    if (current.matches(selector)) return current;
    current = current.parentElement;
  }
  return null;
}
console.log(typeof closestPolyfill);

