class Editor {
  constructor() { this.text = ''; }
  type(t) { this.text += t; }
  save() { return { text: this.text }; }
  restore(s) { this.text = s.text; }
}
const e = new Editor();
e.type('a ');
const snap = e.save();
e.type('b');
e.restore(snap);
console.log(e.text);

